<script setup>
import { computed, ref, toRef } from 'vue'
import { Button, Badge, FormControl, ErrorMessage } from 'frappe-ui'
import VirtualRows from './VirtualRows.vue'
import DocumentForm from './DocumentForm.vue'
import { validateFields } from './formValidation'
const props=defineProps({view:String,threads:Array,contacts:Array,items:Array})
const emit=defineEmits(['open','filter'])
const query=ref(''),category=ref('All'),editing=ref(false),errors=ref({}),draft=ref({}),items=toRef(props,'items')
const contacts=computed(()=>props.contacts.filter(c=>(category.value==='All'||c.type===category.value)&&(c.name+' '+c.company).toLowerCase().includes(query.value.toLowerCase())))
const metrics=computed(()=>[{label:'Open',value:props.threads.filter(t=>t.status==='Open').length,filter:'All'},{label:'Unread',value:props.threads.filter(t=>t.unread>0).length,filter:'Unread'},{label:'Important',value:props.threads.filter(t=>t.important).length,filter:'Important'}])
const fields=computed(()=>props.view==='Canned replies'?[{name:'title',label:'Title',type:'Data',required:true},{name:'channels',label:'Channels',type:'MultiSelect',options:['WhatsApp','Telegram','Email'],required:true},{name:'message',label:'Message',type:'Small Text',required:true,wide:true}]:[{name:'title',label:'Campaign name',type:'Data',required:true},{name:'channel',label:'Channel',type:'Select',options:['WhatsApp','Telegram','Email'],required:true},{name:'recipients',label:'Contacts',type:'MultiSelect',options:props.contacts.filter(c=>c.channels.includes(draft.value.channel)).map(c=>({label:c.name,value:c.id})),required:true,wide:true}])
function create(){draft.value={title:'',channel:'WhatsApp',channels:[],recipients:[],message:''};errors.value={};editing.value=true}
function save(){errors.value=validateFields(fields.value,draft.value);if(props.view==='Campaigns' && (draft.value.recipients||[]).some(id=>!props.contacts.find(c=>c.id===id)?.channels.includes(draft.value.channel)))errors.value.recipients='Select contacts available on this channel.';if(Object.keys(errors.value).length)return;items.value.push({...draft.value,id:'RELAY-DRAFT-'+String(items.value.length+1).padStart(6,'0'),view:props.view});editing.value=false}
</script>
<template>
<div class="page-body">
 <template v-if="view==='Dashboard'"><h2 class="text-xl font-semibold mb-6">My workspace</h2><div class="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8"><button v-for="m in metrics" :key="m.label" class="border rounded-lg p-5 text-left" @click="emit('filter',m.filter)"><span class="block text-sm text-ink-gray-5 mb-3">{{m.label}}</span><strong class="text-2xl">{{m.value}}</strong></button></div><h3 class="text-base font-medium mb-3">Recent conversations</h3><button v-for="t in threads" :key="t.id" class="flex items-center w-full py-4 border-b text-base" @click="emit('open',t.id)"><span>{{t.name}}</span><Badge :label="t.channel" class="ml-3"/><span class="ml-auto text-sm text-ink-gray-5">{{t.team}}</span></button></template>
 <template v-else-if="view==='Contacts'"><div class="flex flex-wrap gap-3 mb-6"><FormControl v-model="query" placeholder="Search contacts" aria-label="Search contacts"/><FormControl v-model="category" type="select" :options="['All','Customer','Supplier','Employee']" label="Business type"/></div><div style="height:calc(100% - 90px);min-height:260px"><VirtualRows :items="contacts" :row-height="104" label="Contacts"><template #default="{item:c}"><div class="contact-row"><div><strong>{{c.name}}</strong><p class="text-sm text-ink-gray-5">{{c.type}} · {{c.record}} · {{c.company}}</p><span v-for="ch in c.channels" :key="ch" class="channel-label" :data-channel="ch">{{ch}}</span></div><Button label="Conversation" @click="emit('open',threads.find(t=>t.contact===c.id)?.id)"/></div></template></VirtualRows></div></template>
 <template v-else-if="['Canned replies','Campaigns'].includes(view)"><div class="flex items-center justify-between mb-6"><h2 class="text-xl font-semibold">{{view}}</h2><div class="flex gap-2"><template v-if="editing"><Button label="Cancel" @click="editing=false"/><Button label="Save draft" variant="solid" @click="save"/></template><Button v-else :label="view==='Campaigns'?'New campaign':'New reply'" icon-left="plus" variant="solid" @click="create"/></div></div><div v-if="editing" class="max-w-3xl mx-auto"><DocumentForm v-model="draft" :fields="fields" :errors="errors"/></div><template v-else><div v-for="item in items.filter(i=>i.view===view)" :key="item.id" class="border-b py-4"><div class="flex gap-3 items-center"><strong class="text-base">{{item.title}}</strong><Badge label="Session draft"/></div><p class="text-sm text-ink-gray-5 mt-2">{{item.message||`${item.channel} · ${item.recipients.length} contacts`}}</p></div><p v-if="!items.some(i=>i.view===view)" class="text-center text-ink-gray-5 text-base py-16">{{view==='Campaigns'?'No campaign drafts':'No canned replies yet'}}</p></template></template>
</div>
</template>
